{"path": "src/lib/tax.ts", "content": "// Sales tax rates by state (decimal). Add a state here before it can be used.
const SALES_TAX_RATES: Record<string, number> = {
  WA: 0.065,
};

export class UnknownTaxStateError extends Error {
  constructor(state: string) {
    super(`No sales tax rate configured for state: ${state}`);
    this.name = 'UnknownTaxStateError';
  }
}

export function salesTaxRate(state: string): number {
  const rate = Object.prototype.hasOwnProperty.call(SALES_TAX_RATES, state)
    ? SALES_TAX_RATES[state]
    : undefined;
  if (rate === undefined) throw new UnknownTaxStateError(state);
  return rate;
}

export function salesTax(taxableAmount: number, state: string): number {
  return Math.round(taxableAmount * salesTaxRate(state) * 100) / 100;
}
"}

