// Only these fields can be edited from the UI. The id is never changed.
export type RulePatch = { id: string } & Partial<Pick<Rule, 'name' | 'threshold' | 'severity'>>;

// Merges patches into the rules currently on disk. Each patch touches only the fields it names,
// so edits to other rules made since the client loaded are kept.
// Writes are serialized so two concurrent saves can't read the same file and overwrite each other.
let queue: Promise<void> = Promise.resolve();

export function mergeRules(patches: RulePatch[], path = RULES_PATH): Promise<void> {
  const run = queue.then(() => doMerge(patches, path));
  queue = run.catch(() => {});
  return run;
}

async function doMerge(patches: RulePatch[], path: string): Promise<void> {
  const current = await loadRules(path);
  const ids = new Set(current.map((r) => r.id));
  const unknown = patches.filter((p) => !ids.has(p.id)).map((p) => `${p.id}: no such rule`);
  if (unknown.length) throw new Error(unknown.join('; '));

  const byId = new Map(patches.map((p) => [p.id, p]));
  const merged = current.map((r) => {
    const p = byId.get(r.id);
    if (!p) return r;
    return {
      ...r,
      ...(p.name !== undefined && { name: p.name }),
      ...(p.threshold !== undefined && { threshold: p.threshold }),
      ...(p.severity !== undefined && { severity: p.severity }),
    };
  });
  await saveRules(merged, path);
}"}

