{"path": "src/server/incidents.ts", "content": "import { replica } from './db';

export type Incident = {
  id: number;
  ruleId: string;
  title: string;
  status: 'open' | 'acknowledged' | 'resolved';
  openedAt: string;
};

export type Page = { items: Incident[]; page: number; pages: number };

export const PAGE_SIZE = 50;

// OFFSET paging: page numbers are 1-based.
export function pageQuery(page: number, limit = PAGE_SIZE): { text: string; values: unknown[] } {
  return {
    text: `SELECT id, rule_id AS "ruleId", title, status,
                  to_char(opened_at AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') AS "openedAt"
             FROM incidents
            ORDER BY opened_at DESC, id DESC
            LIMIT $1 OFFSET $2`,
    values: [limit, (page - 1) * limit],
  };
}

export async function listIncidents(page = 1, limit = PAGE_SIZE): Promise<Page> {
  const current = Math.max(1, Math.floor(page));
  const [{ rows }, count] = await Promise.all([
    replica.query(pageQuery(current, limit)),
    replica.query('SELECT COUNT(*)::int AS n FROM incidents'),
  ]);
  const total: number = count.rows[0].n;
  return { items: rows, page: current, pages: Math.max(1, Math.ceil(total / limit)) };
}
"}

